#[test]
fn session_argument_bounds() {
    let mut c = setup();
    let cases: Vec<(Vec<u8>, u64, Vec<u8>, u32, &str)> = vec![
        (vec![1; 31], EXPIRES_MS, SALT.to_vec(), 3, "32-byte"),
        (pk(7), EXPIRES_MS, vec![9; 15], 3, "Salt must be 16-64 bytes"),
        (pk(7), EXPIRES_MS, vec![9; 65], 3, "Salt must be 16-64 bytes"),
        (pk(7), NOW_MS, SALT.to_vec(), 3, "within 24 hours"),
        (pk(7), NOW_MS + 24 * HOUR_MS + 1, SALT.to_vec(), 3, "within 24 hours"),
        (pk(7), EXPIRES_MS, SALT.to_vec(), 0, "max_uses must be 1-500"),
        (pk(7), EXPIRES_MS, SALT.to_vec(), 501, "max_uses must be 1-500"),
    ];
    for (key, expires, salt, max_uses, expected) in cases {
        let err = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            c.create_session(tok("session_a"), key.clone(), expires, salt.clone(), 0, max_uses);
        }))
        .expect_err(expected);
        let msg = panic_msg(err);
        assert!(msg.contains(expected), "{msg} should contain {expected}");
    }
}

#[test]
fn derive_key_calls_the_mpc_with_the_session_path() {
    let mut c = setup();
    open(&mut c, "session_a", 7, 0);
    derive(&mut c, 7, 1);
    assert_eq!(c.get_session(pk(7)).unwrap().used, 1);
    let receipts = get_created_receipts();
    assert_eq!(receipts.len(), 1);
    assert_eq!(receipts[0].receiver_id, acc("v1.signer-prod.testnet"));
    let MockAction::FunctionCallWeight { method_name, args, attached_deposit, prepaid_gas, .. } = &receipts[0].actions[0] else { panic!() };
    assert_eq!(method_name, b"request_app_private_key");
    assert_eq!(*attached_deposit, NearToken::from_yoctonear(1));
    assert_eq!(prepaid_gas.as_tgas(), 20);
    let args: Value = serde_json::from_slice(args).unwrap();
    assert_eq!(
        args,
        serde_json::json!({"request":{"derivation_path":format!("s1#google#{USER}#0"),"app_public_key":{"AppPublicKeyPV":{"pk1":"bls12381g1:A","pk2":"bls12381g2:B"}},"domain_id":2}})
    );
}

