#[test]
fn rejects_invalid_rsa_exponents() {
    let mut c = setup();
    let n = fixture()["n"].as_str().unwrap().to_string();
    // 1 ("AQ"; with e = 1 every signature is its own message, so anyone could forge tokens), even, empty,
    // 9 bytes, and 1 hidden behind leading zeros.
    for e in ["AQ", "Ag", "AQAA", "", &oidc::b64url(&[1; 9]), "AAAB"] {
        let err = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            c.set_issuer_key("google".into(), "bad-e".into(), n.clone(), e.to_string());
        }))
        .expect_err(e);
        let msg = panic_msg(err);
        assert!(msg.contains("Invalid RSA exponent"), "e = {e:?}: {msg}");
    }
    assert_eq!(c.get_issuer("google".into()).unwrap().kids, vec!["test-kid".to_string()]);
    // The usual exponent (65537) and 3 are accepted.
    c.set_issuer_key("google".into(), "e3".into(), n.clone(), "Aw".into());
    c.set_issuer_key("google".into(), "e65537".into(), n, "AQAB".into());
}

/// Adds issuer "other" (iss https://other.example) holding kid test-kid2 = the fixture's other RSA key.
fn with_other_issuer(c: &mut HanaSigner) {
    let f = fixture();
    ctx(ADMIN, NOW_MS);
    c.set_issuer("other".into(), vec!["https://other.example".into()]);
    c.set_issuer_key("other".into(), f["other_kid"].as_str().unwrap().into(), f["other_n"].as_str().unwrap().into(), f["other_e"].as_str().unwrap().into());
}

#[test]
fn a_kid_only_verifies_tokens_of_its_own_issuer() {
    let mut c = setup();
    with_other_issuer(&mut c);
    // Control: the other issuer's own token verifies (as provider "other", which has no registered client).
    let err = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        open(&mut c, "session_other_issuer", 7, 0);
    }))
    .unwrap_err();
    assert!(panic_msg(err).contains("Token is for an unregistered app"));
    // A google-iss token signed by the other issuer's key, under that key's kid.
    for token in ["session_google_iss_other_kid", "session_other_iss_google_kid"] {
        let err = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            open(&mut c, token, 7, 0);
        }))
        .expect_err(token);
        let msg = panic_msg(err);
        assert!(msg.contains("Unknown signing key"), "{token}: {msg}");
    }
}

