#[test]
fn register_scope_charges_storage_and_refunds_the_excess() {
    let mut c = public();
    // In wasm every call starts with nothing cached; flush setup()'s writes so only this call's storage is counted.
    c.scopes.flush();
    c.client_index.flush();
    ctx_with(MALLORY, NOW_MS, NearToken::from_near(1));
    c.register_scope(reg_owners(), vec![tok("reg_c")]);
    let refunds = transfers();
    assert_eq!(refunds.len(), 1);
    assert_eq!(refunds[0].0, MALLORY);
    let charged = NearToken::from_near(1).as_yoctonear() - refunds[0].1;
    assert!(charged > 0 && charged < NearToken::from_millinear(50).as_yoctonear(), "charged {charged}");
    println!("register_scope storage charge (1 client, 2 owners): {charged} yoctoNEAR");
}

