// A removed client is quarantined: until free_at_ms only its old scope may take it back. Here alice (a co-owner of
// s1) removes A2 and bob (owner of s2) or a fresh registrant tries to take it.

fn remove_a2_from_s1(c: &mut HanaSigner) {
    ctx(ALICE, NOW_MS);
    c.remove_client("s1".into(), OwnerAuth::Near, "google".into(), A2.into());
}

#[test]
fn a_removed_client_cannot_be_proposed_elsewhere_until_free() {
    let mut c = setup();
    remove_a2_from_s1(&mut c);
    ctx(BOB, NOW_MS + DELAY_MS - 1);
    let err = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        c.propose_change("s2".into(), OwnerAuth::Near, add(A2), Some(tok("cp_a2_s2_0")));
    }))
    .unwrap_err();
    assert!(panic_msg(err).contains("Client was recently removed from another scope"));
    // Once free, another scope may take it (with its own timelock).
    ctx(BOB, NOW_MS + DELAY_MS);
    let id = c.propose_change("s2".into(), OwnerAuth::Near, add(A2), Some(tok("cp_a2_s2_0")));
    ctx(BOB, NOW_MS + 2 * DELAY_MS);
    c.execute_change("s2".into(), id);
    assert_eq!(c.scope_for_client("google".into(), A2.into()), Some("s2".into()));
    assert!(c.removed_clients.get(&google(A2)).is_none());
}

#[test]
fn the_old_scope_can_re_add_a_removed_client_at_once() {
    let mut c = setup();
    remove_a2_from_s1(&mut c); // action_nonce 0 → 1
    let id = c.propose_change("s1".into(), OwnerAuth::Near, add(A2), Some(tok("cp_a2_s1_1")));
    ctx(ALICE, NOW_MS + DELAY_MS);
    c.execute_change("s1".into(), id);
    assert_eq!(c.scope_for_client("google".into(), A2.into()), Some("s1".into()));
    assert!(c.removed_clients.get(&google(A2)).is_none());
}

#[test]
#[should_panic(expected = "Client was recently removed from another scope")]
fn a_stale_proposal_elsewhere_cannot_take_a_just_removed_client() {
    let mut c = setup();
    // s1 and s2 race for E; s1 wins. Later an s1 owner removes E: s2's old proposal must not take it at once.
    propose_e(&mut c);
    ctx(BOB, NOW_MS);
    c.propose_change("s2".into(), OwnerAuth::Near, add(E), Some(tok("cp_e_s2_0")));
    ctx(ALICE, NOW_MS + DELAY_MS);
    c.execute_change("s1".into(), 0);
    c.remove_client("s1".into(), OwnerAuth::Near, "google".into(), E.into());
    c.execute_change("s2".into(), 0);
}

#[test]
fn a_removed_client_cannot_be_registered_until_free() {
    let mut c = setup();
    remove_a2_from_s1(&mut c);
    ctx(ADMIN, NOW_MS);
    let err = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        c.admin_register_scope(vec![near_owner(MALLORY)], vec![google(A2)], None);
    }))
    .unwrap_err();
    assert!(panic_msg(err).contains("Client was recently removed from another scope"));
    c.enable_public_registration();
    ctx(RELAYER, NOW_MS + DELAY_MS - 1);
    let err = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        c.register_scope(vec![near_owner(MALLORY)], vec![tok("reg_a2_mallory")]);
    }))
    .unwrap_err();
    assert!(panic_msg(err).contains("Client was recently removed from another scope"));
    ctx(RELAYER, NOW_MS + DELAY_MS);
    let id = c.register_scope(vec![near_owner(MALLORY)], vec![tok("reg_a2_mallory")]);
    assert_eq!(c.scope_for_client("google".into(), A2.into()), Some(id));
    assert!(c.removed_clients.get(&google(A2)).is_none());
}

