// ---- JSON shapes shared with the API ----

#[test]
fn json_shapes() {
    assert_eq!(serde_json::to_string(&OwnerAuth::Near).unwrap(), r#""Near""#);
    let auth: OwnerAuth = serde_json::from_str(r#"{"Oidc":{"jwt":"x"}}"#).unwrap();
    assert!(matches!(auth, OwnerAuth::Oidc { jwt } if jwt == "x"));
    assert_eq!(serde_json::to_string(&add(E)).unwrap(), format!(r#"{{"AddClient":{{"provider":"google","aud":"{E}"}}}}"#));
    assert_eq!(
        serde_json::to_string(&Change::SetOwners { owners: vec![near_owner(ALICE), oidc_owner("1")] }).unwrap(),
        r#"{"SetOwners":{"owners":[{"Near":{"account_id":"alice.testnet"}},{"Oidc":{"provider":"google","sub":"1"}}]}}"#
    );
    let req = CkdRequestArgs { derivation_path: "s1#google#1#0".into(), app_public_key: CkdAppPublicKey::AppPublicKeyPV { pk1: "bls12381g1:x".into(), pk2: "bls12381g2:y".into() }, domain_id: 2 };
    assert_eq!(
        serde_json::to_string(&req).unwrap(),
        r#"{"derivation_path":"s1#google#1#0","app_public_key":{"AppPublicKeyPV":{"pk1":"bls12381g1:x","pk2":"bls12381g2:y"}},"domain_id":2}"#
    );
}
